63	    private static final List<String[]> knownIdleStackFrames = Arrays.asList(
64	        new String[] { "java.util.concurrent.ThreadPoolExecutor", "getTask" },
65	        new String[] { "sun.nio.ch.SelectorImpl", "select" },
66	        new String[] { "org.elasticsearch.threadpool.ThreadPool$CachedTimeThread", "run" },
