72	    // NOTE: these are JVM dependent and JVM version dependent
73	    private static final List<String> knownJDKInternalThreads = Arrays.asList(
74	        "Signal Dispatcher",
75	        "Finalizer",
76	        "Reference Handler",
77	        "Notification Thread",
78	        "Common-Cleaner",
79	        "process reaper",
