83	    /**
84	     * Capture and log the hot threads on the local node. Useful for capturing stack traces for unexpectedly-slow operations in production.
85	     * The resulting log message may be large, and contains significant whitespace, so it is compressed and base64-encoded using {@link
86	     * ChunkedLoggingStream}.
87	     *
88	     * @param logger        The logger to use for the logging
89	     * @param level         The log level to use for the logging.
90	     * @param prefix        The prefix to emit on each chunk of the logging.
91	     * @param referenceDocs A link to the docs describing how to decode the logging.
92	     */
93	    public static void logLocalHotThreads(Logger logger, Level level, String prefix, ReferenceDocs referenceDocs) {
94	        if (logger.isEnabled(level) == false) {
95	            return;
96	        }
97	
98	        try (
99	            var stream = ChunkedLoggingStream.create(logger, level, prefix, referenceDocs);
100	            var writer = new OutputStreamWriter(stream, StandardCharsets.UTF_8)
101	        ) {
102	            new HotThreads().busiestThreads(500).ignoreIdleThreads(false).detect(writer);
103	        } catch (Exception e) {
104	            logger.error(() -> org.elasticsearch.common.Strings.format("failed to write local hot threads with prefix [%s]", prefix), e);
105	        }
106	    }
