108	    /**
109	     * Capture and log the current threads on the local node. Unlike hot threads this does not sample and captures current state only.
110	     * Useful for capturing stack traces for unexpectedly-slow operations in production. The resulting log message may be large, and
111	     * contains significant whitespace, so it is compressed and base64-encoded using {@link ChunkedLoggingStream}.
112	     *
113	     * @param logger        The logger to use for the logging
114	     * @param level         The log level to use for the logging.
115	     * @param prefix        The prefix to emit on each chunk of the logging.
116	     * @param referenceDocs A link to the docs describing how to decode the logging.
117	     */
118	    public static void logLocalCurrentThreads(Logger logger, Level level, String prefix, ReferenceDocs referenceDocs) {
119	        if (logger.isEnabled(level) == false) {
120	            return;
121	        }
122	
123	        try (
124	            var stream = ChunkedLoggingStream.create(logger, level, prefix, referenceDocs);
125	            var writer = new OutputStreamWriter(stream, StandardCharsets.UTF_8)
126	        ) {
127	            new HotThreads().busiestThreads(500).threadElementsSnapshotCount(1).detect(writer);
128	        } catch (Exception e) {
129	            logger.error(
130	                () -> org.elasticsearch.common.Strings.format("failed to write local current threads with prefix [%s]", prefix),
131	                e
132	            );
133	        }
134	    }
