232	    static boolean isKnownJDKThread(ThreadInfo threadInfo) {
233	        return (knownJDKInternalThreads.stream()
234	            .anyMatch(jvmThread -> threadInfo.getThreadName() != null && threadInfo.getThreadName().equals(jvmThread)));
235	    }
236	
237	    static boolean isKnownIdleStackFrame(String className, String methodName) {
238	        return (knownIdleStackFrames.stream().anyMatch(pair -> pair[0].equals(className) && pair[1].equals(methodName)));
239	    }
240	
241	    static boolean isIdleThread(ThreadInfo threadInfo) {
242	        if (isKnownJDKThread(threadInfo)) {
243	            return true;
244	        }
245	
246	        for (StackTraceElement frame : threadInfo.getStackTrace()) {
247	            if (isKnownIdleStackFrame(frame.getClassName(), frame.getMethodName())) {
248	                return true;
249	            }
250	        }
251	
252	        return false;
253	    }
