255	    Map<Long, ThreadTimeAccumulator> getAllValidThreadInfos(ThreadMXBean threadBean, SunThreadInfo sunThreadInfo, long currentThreadId) {
256	        long[] threadIds = threadBean.getAllThreadIds();
257	        ThreadInfo[] threadInfos = threadBean.getThreadInfo(threadIds);
258	        Map<Long, ThreadTimeAccumulator> result = Maps.newMapWithExpectedSize(threadIds.length);
259	
260	        for (int i = 0; i < threadIds.length; i++) {
261	            if (threadInfos[i] == null || threadIds[i] == currentThreadId) {
262	                continue;
263	            }
264	            long cpuTime = threadBean.getThreadCpuTime(threadIds[i]);
265	            if (cpuTime == INVALID_TIMING) {
266	                continue;
267	            }
268	            long allocatedBytes = type == ReportType.MEM ? sunThreadInfo.getThreadAllocatedBytes(threadIds[i]) : 0;
269	            result.put(threadIds[i], new ThreadTimeAccumulator(threadInfos[i], interval, cpuTime, allocatedBytes));
270	        }
271	
272	        return result;
273	    }
274	
275	    ThreadInfo[][] captureThreadStacks(ThreadMXBean threadBean, long[] threadIds) throws InterruptedException {
276	        ThreadInfo[][] result = new ThreadInfo[threadElementsSnapshotCount][];
277	
278	        // NOTE, javadoc of getThreadInfo says: If a thread of the given ID is not alive or does not exist,
279	        // null will be set in the corresponding element in the returned array. A thread is alive if it has
280	        // been started and has not yet died.
281	        for (int j = 0; j < threadElementsSnapshotCount - 1; j++) {
282	            result[j] = threadBean.getThreadInfo(threadIds, Integer.MAX_VALUE);
283	            Thread.sleep(threadElementsSnapshotDelay.millis());
284	        }
285	        result[threadElementsSnapshotCount - 1] = threadBean.getThreadInfo(threadIds, Integer.MAX_VALUE);
286	
287	        return result;
288	    }
