290	    private static boolean isThreadWaitBlockTimeMonitoringEnabled(ThreadMXBean threadBean) {
291	        if (threadBean.isThreadContentionMonitoringSupported()) {
292	            return threadBean.isThreadContentionMonitoringEnabled();
293	        }
294	        return false;
295	    }
