297	    private double getTimeSharePercentage(long time) {
298	        return (((double) time) / interval.nanos()) * 100;
299	    }
300	
301	    void innerDetect(ThreadMXBean threadBean, SunThreadInfo sunThreadInfo, long currentThreadId, Writer writer, Runnable onNextThread)
302	        throws Exception {
303	        if (threadBean.isThreadCpuTimeSupported() == false) {
304	            throw new ElasticsearchException("thread CPU time is not supported on this JDK");
305	        }
306	
307	        if (type == ReportType.MEM && sunThreadInfo.isThreadAllocatedMemorySupported() == false) {
308	            throw new ElasticsearchException("thread allocated memory is not supported on this JDK");
309	        }
310	
311	        // Enabling thread contention monitoring is required for capturing JVM thread wait/blocked times. If we weren't
312	        // able to enable this functionality during bootstrap, we should not produce HotThreads reports.
313	        if (isThreadWaitBlockTimeMonitoringEnabled(threadBean) == false) {
314	            throw new ElasticsearchException("thread wait/blocked time accounting is not supported on this JDK");
315	        }
316	
317	        writer.append("Hot threads at ")
318	            .append(DATE_TIME_FORMATTER.format(LocalDateTime.now(Clock.systemUTC())))
319	            .append(", interval=")
320	            .append(interval.toString())
321	            .append(", busiestThreads=")
322	            .append(Integer.toString(busiestThreads))
323	            .append(", ignoreIdleThreads=")
324	            .append(Boolean.toString(ignoreIdleThreads))
325	            .append(":\n");
326	        onNextThread.run();
327	
328	        // Capture before and after thread state with timings
329	        Map<Long, ThreadTimeAccumulator> previousThreadInfos = getAllValidThreadInfos(threadBean, sunThreadInfo, currentThreadId);
330	        Thread.sleep(interval.millis());
331	        Map<Long, ThreadTimeAccumulator> latestThreadInfos = getAllValidThreadInfos(threadBean, sunThreadInfo, currentThreadId);
332	
333	        latestThreadInfos.forEach((threadId, accumulator) -> accumulator.subtractPrevious(previousThreadInfos.get(threadId)));
334	
335	        // Sort by delta CPU time on thread.
336	        List<ThreadTimeAccumulator> topThreads = new ArrayList<>(latestThreadInfos.values());
337	
338	        // Special comparator for CPU mode with TOTAL sort type only. Otherwise, we simply use the value.
339	        if (type == ReportType.CPU && sortOrder == SortOrder.TOTAL) {
340	            CollectionUtil.introSort(
341	                topThreads,
342	                Comparator.comparingLong(ThreadTimeAccumulator::getRunnableTime)
343	                    .thenComparingLong(ThreadTimeAccumulator::getCpuTime)
344	                    .reversed()
345	            );
346	        } else {
347	            CollectionUtil.introSort(topThreads, Comparator.comparingLong(ThreadTimeAccumulator.valueGetterForReportType(type)).reversed());
348	        }
349	
350	        topThreads = topThreads.subList(0, Math.min(busiestThreads, topThreads.size()));
351	        long[] topThreadIds = topThreads.stream().mapToLong(t -> t.threadId).toArray();
352	
353	        // analyse N stack traces for the top threads
354	        ThreadInfo[][] allInfos = captureThreadStacks(threadBean, topThreadIds);
355	
356	        for (int t = 0; t < topThreads.size(); t++) {
357	            String threadName = null;
358	            for (ThreadInfo[] info : allInfos) {
359	                if (info != null && info[t] != null) {
360	                    if (ignoreIdleThreads && isIdleThread(info[t])) {
361	                        info[t] = null;
362	                        continue;
363	                    }
364	                    threadName = info[t].getThreadName();
365	                    break;
366	                }
367	            }
368	            if (threadName == null) {
369	                continue; // thread is not alive yet or died before the first snapshot - ignore it!
370	            }
371	
372	            ThreadTimeAccumulator topThread = topThreads.get(t);
373	
374	            switch (type) {
375	                case MEM -> writer.append(
376	                    Strings.format(
377	                        "%n%s memory allocated by thread '%s'%n",
378	                        ByteSizeValue.ofBytes(topThread.getAllocatedBytes()),
379	                        threadName
380	                    )
381	                );
382	                case CPU -> {
383	                    double percentCpu = getTimeSharePercentage(topThread.getCpuTime());
384	                    double percentOther = Transports.isTransportThread(threadName) && topThread.getCpuTime() == 0L
385	                        ? 100.0
386	                        : getTimeSharePercentage(topThread.getOtherTime());
387	                    double percentTotal = (Transports.isTransportThread(threadName)) ? percentCpu : percentOther + percentCpu;
388	                    String otherLabel = (Transports.isTransportThread(threadName)) ? "idle" : "other";
389	                    writer.append(
390	                        Strings.format(
391	                            "%n%4.1f%% [cpu=%1.1f%%, %s=%1.1f%%] (%s out of %s) %s usage by thread '%s'%n",
392	                            percentTotal,
393	                            percentCpu,
394	                            otherLabel,
395	                            percentOther,
396	                            TimeValue.timeValueNanos(topThread.getCpuTime() + topThread.getOtherTime()),
397	                            interval,
398	                            type.getTypeValue(),
399	                            threadName
400	                        )
401	                    );
402	                }
403	                default -> {
404	                    long time = ThreadTimeAccumulator.valueGetterForReportType(type).applyAsLong(topThread);
405	                    double percent = getTimeSharePercentage(time);
406	                    writer.append(
407	                        Strings.format(
408	                            "%n%4.1f%% (%s out of %s) %s usage by thread '%s'%n",
409	                            percent,
410	                            TimeValue.timeValueNanos(time),
411	                            interval,
412	                            type.getTypeValue(),
413	                            threadName
414	                        )
415	                    );
416	                }
417	            }
418	
419	            // for each snapshot (2nd array index) find later snapshot for same thread with max number of
420	            // identical StackTraceElements (starting from end of each)
421	            boolean[] done = new boolean[threadElementsSnapshotCount];
422	            for (int i = 0; i < threadElementsSnapshotCount; i++) {
423	                if (done[i]) continue;
424	                int maxSim = 1;
425	                boolean[] similars = new boolean[threadElementsSnapshotCount];
426	                for (int j = i + 1; j < threadElementsSnapshotCount; j++) {
427	                    if (done[j]) continue;
428	                    int similarity = similarity(allInfos[i][t], allInfos[j][t]);
429	                    if (similarity > maxSim) {
430	                        maxSim = similarity;
431	                        similars = new boolean[threadElementsSnapshotCount];
432	                    }
433	                    if (similarity == maxSim) similars[j] = true;
434	                }
435	                // print out trace maxSim levels of i, and mark similar ones as done
436	                int count = 1;
437	                for (int j = i + 1; j < threadElementsSnapshotCount; j++) {
438	                    if (similars[j]) {
439	                        done[j] = true;
440	                        count++;
441	                    }
442	                }
443	                if (allInfos[i][t] != null) {
444	                    final StackTraceElement[] show = allInfos[i][t].getStackTrace();
445	                    if (count == 1) {
446	                        writer.append(Strings.format("  unique snapshot%n"));
447	                        for (StackTraceElement frame : show) {
448	                            writer.append(Strings.format("    %s%n", frame));
449	                        }
450	                    } else {
451	                        writer.append(
452	                            Strings.format("  %d/%d snapshots sharing following %d elements%n", count, threadElementsSnapshotCount, maxSim)
453	                        );
454	                        for (int l = show.length - maxSim; l < show.length; l++) {
455	                            writer.append(Strings.format("    %s%n", show[l]));
456	                        }
457	                    }
458	                }
459	            }
460	            onNextThread.run();
461	        }
462	    }
463	
464	    static int similarity(ThreadInfo threadInfo, ThreadInfo threadInfo0) {
465	        StackTraceElement[] s1 = threadInfo == null ? EMPTY : threadInfo.getStackTrace();
466	        StackTraceElement[] s2 = threadInfo0 == null ? EMPTY : threadInfo0.getStackTrace();
467	        int i = s1.length - 1;
468	        int j = s2.length - 1;
469	        int rslt = 0;
470	        while (i >= 0 && j >= 0 && s1[i].equals(s2[j])) {
471	            rslt++;
472	            i--;
473	            j--;
474	        }
475	        return rslt;
476	    }
