478	    static class ThreadTimeAccumulator {
479	        private final long threadId;
480	        private final String threadName;
481	        private final TimeValue interval;
482	        private long cpuTime;
483	        private long blockedTime;
484	        private long waitedTime;
485	        private long allocatedBytes;
486	
487	        ThreadTimeAccumulator(ThreadInfo info, TimeValue interval, long cpuTime, long allocatedBytes) {
488	            this.blockedTime = millisecondsToNanos(info.getBlockedTime()); // Convert to nanos to standardize
489	            this.waitedTime = millisecondsToNanos(info.getWaitedTime()); // Convert to nanos to standardize
490	            this.cpuTime = cpuTime;
491	            this.allocatedBytes = allocatedBytes;
492	            this.threadId = info.getThreadId();
493	            this.threadName = info.getThreadName();
494	            this.interval = interval;
495	        }
496	
497	        private static long millisecondsToNanos(long millis) {
498	            return millis * 1_000_000;
499	        }
500	
501	        void subtractPrevious(ThreadTimeAccumulator previous) {
502	            // Previous can be null for threads that had started while we were sleeping.
503	            // In that case the absolute thread timings are the delta.
504	            if (previous != null) {
505	                if (previous.getThreadId() != getThreadId()) {
506	                    throw new IllegalStateException("Thread timing accumulation must be done on the same thread");
507	                }
508	                this.blockedTime -= previous.blockedTime;
509	                this.waitedTime -= previous.waitedTime;
510	                this.cpuTime -= previous.cpuTime;
511	                this.allocatedBytes -= previous.allocatedBytes;
512	            }
513	        }
514	
515	        // A thread can migrate a CPU while executing, in which case, on certain processors, the
516	        // reported timings will be bogus (and likely negative). We cap the reported timings to >= 0 values only.
517	        public long getCpuTime() {
518	            return Math.max(cpuTime, 0);
519	        }
520	
521	        public long getRunnableTime() {
522	            // If the thread didn't have any CPU movement, we can't really tell if it's
523	            // not running, or it has been asleep forever.
524	            if (getCpuTime() == 0) {
525	                return 0;
526	            } else if (Transports.isTransportThread(threadName)) {
527	                return getCpuTime();
528	            }
529	            return Math.max(interval.nanos() - getWaitedTime() - getBlockedTime(), 0);
530	        }
531	
532	        public long getOtherTime() {
533	            // If the thread didn't have any CPU movement, we can't really tell if it's
534	            // not running, or it has been asleep forever.
535	            if (getCpuTime() == 0) {
536	                return 0;
537	            }
538	
539	            return Math.max(interval.nanos() - getWaitedTime() - getBlockedTime() - getCpuTime(), 0);
540	        }
541	
542	        public long getBlockedTime() {
543	            return Math.max(blockedTime, 0);
544	        }
545	
546	        public long getWaitedTime() {
547	            return Math.max(waitedTime, 0);
548	        }
549	
550	        public long getAllocatedBytes() {
551	            return Math.max(allocatedBytes, 0);
552	        }
553	
554	        public long getThreadId() {
555	            return threadId;
556	        }
557	
558	        static ToLongFunction<ThreadTimeAccumulator> valueGetterForReportType(ReportType type) {
559	            return switch (type) {
560	                case CPU -> ThreadTimeAccumulator::getCpuTime;
561	                case WAIT -> ThreadTimeAccumulator::getWaitedTime;
562	                case BLOCK -> ThreadTimeAccumulator::getBlockedTime;
563	                case MEM -> ThreadTimeAccumulator::getAllocatedBytes;
564	            };
565	        }
566	    }
