573	    public static void initializeRuntimeMonitoring() {
574	        // We'll let the JVM boot without this functionality, however certain APIs like HotThreads will not
575	        // function and report an error.
576	        if (ManagementFactory.getThreadMXBean().isThreadContentionMonitoringSupported() == false) {
577	            LogManager.getLogger(HotThreads.class).info("Thread wait/blocked time accounting not supported.");
578	        } else {
579	            try {
580	                ManagementFactory.getThreadMXBean().setThreadContentionMonitoringEnabled(true);
581	            } catch (UnsupportedOperationException monitoringUnavailable) {
582	                LogManager.getLogger(HotThreads.class).warn("Thread wait/blocked time accounting cannot be enabled.");
583	            }
584	        }
585	    }
