587	    public record RequestOptions(
588	        int threads,
589	        HotThreads.ReportType reportType,
590	        HotThreads.SortOrder sortOrder,
591	        TimeValue interval,
592	        int snapshots,
593	        boolean ignoreIdleThreads
594	    ) implements Writeable {
595	
596	        public static RequestOptions readFrom(StreamInput in) throws IOException {
597	            var threads = in.readInt();
598	            var ignoreIdleThreads = in.readBoolean();
599	            var reportType = HotThreads.ReportType.of(in.readString());
600	            var interval = in.readTimeValue();
601	            var snapshots = in.readInt();
602	            var sortOrder = HotThreads.SortOrder.of(in.readString());
603	            return new RequestOptions(threads, reportType, sortOrder, interval, snapshots, ignoreIdleThreads);
604	        }
605	
606	        @Override
607	        public void writeTo(StreamOutput out) throws IOException {
608	            out.writeInt(threads);
609	            out.writeBoolean(ignoreIdleThreads);
610	            out.writeString(reportType.getTypeValue());
611	            out.writeTimeValue(interval);
